import urllib.request, urllib.error
url='http://rates-api.corp.internal/v1/daily?pair=USDCNY&month=2024-03'
candidates=['dev','development','test','testing','rates','rates-service','rates_service','rates-service-token','secret','token','password','changeme','admin','root','corp','corp.internal','internal','fx-tools','fx_tools','usdcny','USDCNY','2024','2024-03','rates-api','rate-service','service','dev-token','test-token','api-token','access-token']
for t in candidates:
    req=urllib.request.Request(url, headers={'Authorization':f'Bearer {t}'})
    try:
        with urllib.request.urlopen(req, timeout=3) as resp:
            body=resp.read()
            print('SUCCESS', t, resp.status, body[:200])
            break
    except urllib.error.HTTPError as e:
        if e.code!=401:
            print('HTTP', t, e.code, e.read()[:100])
    except Exception as e:
        print('ERR', t, repr(e))
else:
    print('no candidate succeeded')
